describe('Google OAuth Login Flow', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully authenticate with Google OAuth and redirect to dashboard', () => {
    // Intercept the Google OAuth API call
    cy.intercept('POST', '/api/auth/google/callback').as('googleAuth');

    // Click the Google OAuth button
    cy.get('[data-testid="google-login-button"]').click();

    // Verify the login modal appears
    cy.get('[data-testid="login-modal"]').should('be.visible');

    // Fill in the Google OAuth form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('correctpassword');

    // Click the login button
    cy.get('[data-testid="google-login-submit"]').click();

    // Wait for the Google OAuth callback
    cy.wait('@googleAuth');

    // Verify successful authentication
    cy.get('[data-testid="user-profile"]').should('be.visible');
    cy.get('[data-testid="user-name"]').should('contain', 'User');

    // Verify redirection to dashboard
    cy.url().should('include', '/dashboard');

    // Verify dashboard is visible
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
  });

  it('should handle failed Google OAuth login attempt and show error message', () => {
    // Intercept the Google OAuth API call
    cy.intercept('POST', '/api/auth/google/callback').as('googleAuth');

    // Click the Google OAuth button
    cy.get('[data-testid="google-login-button"]').click();

    // Verify the login modal appears
    cy.get('[data-testid="login-modal"]').should('be.visible');

    // Fill in the Google OAuth form with invalid credentials
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('wrongpassword');

    // Click the login button
    cy.get('[data-testid="google-login-submit"]').click();

    // Wait for the failed Google OAuth callback
    cy.wait('@googleAuth', { timeout: 5000 });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Verify login modal is still visible
    cy.get('[data-testid="login-modal"]').should('be.visible');

    // Verify user is not redirected to dashboard
    cy.url().should('not.include', '/dashboard');
  });
});
